import { call, put, takeLatest } from "redux-saga/effects";
import api from "../../api/axios";
import {
  fetchDestinations,
  fetchDestinationsSuccess,
  fetchDestinationsFailure,
} from "./slice";

function* fetchDestinationsWorker() {
  try {
    const { data } = yield call(api.get, "/destinations");
    const items = data.map((d) => ({
      id: d.id,
      value: d.id,
      label: d.name,
    }));
    yield put(fetchDestinationsSuccess(items));
  } catch (e) {
    yield put(fetchDestinationsFailure(e.message));
  }
}

export default function* destinationsSaga() {
  yield takeLatest(fetchDestinations.type, fetchDestinationsWorker);
}
