import { createSlice } from "@reduxjs/toolkit";

const initialState = { items: [], loading: false, error: null };

const hotelsSlice = createSlice({
  name: "hotels",
  initialState,
  reducers: {
    fetchHotels(state, _action) {
      state.loading = true;
      state.error = null;
    },
    fetchHotelsSuccess(state, { payload }) {
      state.loading = false;
      state.items = payload;
    },
    fetchHotelsFailure(state, { payload }) {
      state.loading = false;
      state.error = payload || "Failed";
    },
  },
});

export const { fetchHotels, fetchHotelsSuccess, fetchHotelsFailure } =
  hotelsSlice.actions;
export default hotelsSlice.reducer;
