import { Container, AppBar, Toolbar, Button, Typography } from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import AppRoutes from './routes';

export default function App() {
  return (
    <>
      <AppBar position="static">
        <Toolbar sx={{ gap: 2 }}>
          <Typography variant="h6" sx={{ flexGrow: 1 }}>Booking</Typography>
          <Button component={RouterLink} to="/" color="inherit">Main</Button>
          <Button component={RouterLink} to="/hotels" color="inherit">Hotels</Button>
          <Button component={RouterLink} to="/about" color="inherit">About</Button>
        </Toolbar>
      </AppBar>
      <Container sx={{ mt: 3 }}>
        <AppRoutes />
      </Container>
    </>
  );
}
