import { Card, CardContent, Typography } from '@mui/material';

export default function HotelCard({ h }) {
  return (
    <Card>
      <CardContent>
        <Typography variant="h6">{h.name}</Typography>
        <Typography color="text.secondary">{h.address}</Typography>
        <Typography>{h.city} • Rating: {h.hotel_rating ?? '—'}</Typography>
      </CardContent>
    </Card>
  );
}
