import { useSelector } from 'react-redux';
import { Grid, Alert, CircularProgress, Typography } from '@mui/material';
import HotelCard from '../components/HotelCard';

export default function Hotels() {
  const { items, loading, error, lastQuery } = useSelector(s => s.hotels);

  if (loading) return <CircularProgress />;
  if (error) return <Alert severity="error">{error}</Alert>;

  return (
    <>
      <Typography variant="h5" sx={{ mb: 2 }}>
        Hotels {lastQuery?.destinationLabel ? `in ${lastQuery.destinationLabel}` : ''}
      </Typography>
      <Grid container spacing={2}>
        {items.map(h => (
          <Grid item xs={12} sm={6} md={4} key={h.id}>
            <HotelCard h={h} />
          </Grid>
        ))}
      </Grid>
    </>
  );
}
