import { takeLatest, call, put } from "redux-saga/effects";
import api from "../../api/axios";
import { fetchHotels, fetchHotelsSuccess, fetchHotelsFailure } from "./slice";
import { push } from "redux-first-history";

function* worker({ payload }) {
  try {
    const params = { city: payload.destinationLabel };
    const { data } = yield call(api.get, "/hotels", { params });
    yield put(fetchHotelsSuccess(data));
    yield put(push("/hotels"));
  } catch (e) {
    yield put(fetchHotelsFailure(e.message));
  }
}

export default function* hotelsSaga() {
  yield takeLatest(fetchHotels.type, worker);
}
