import { Form, Field } from 'react-final-form';
import { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { fetchDestinations } from '../features/destinations/slice';
import { fetchHotels } from '../features/hotels/slice';
import {
  TextField, MenuItem, Stack, Button, Paper, Typography
} from '@mui/material';

const required = (v) => (v ? undefined : 'Required');

export default function BookingForm() {
  const dispatch = useDispatch();


  const { items: destinations = [], loading = false } =
    useSelector((s) => s.destinations ?? { items: [], loading: false });

  useEffect(() => { dispatch(fetchDestinations()); }, [dispatch]);

  const onSubmit = (values) => {
    const dest = destinations.find(d => String(d.value) === String(values.destination));
    const destinationLabel = dest?.label;
    dispatch(fetchHotels({ destinationLabel, ...values }));
  };

  return (
    <Paper sx={{ p: 3 }}>
      <Typography variant="h5" sx={{ mb: 2 }}>Find your hotel</Typography>
      <Form
        onSubmit={onSubmit}
        render={({ handleSubmit, submitting, pristine }) => (
          <form onSubmit={handleSubmit}>
            <Stack spacing={2}>
              <Field name="destination" validate={required}>
                {({ input, meta }) => (
                  <TextField
                    select
                    label="Destination"
                    {...input}
                    helperText={meta.touched && meta.error}
                    error={meta.touched && !!meta.error}
                    disabled={loading}
                  >
                    {(destinations ?? []).map((opt) => (
                      <MenuItem key={opt.id ?? opt.value} value={opt.value}>
                        {opt.label}
                      </MenuItem>
                    ))}
                    {!loading && destinations.length === 0 && (
                      <MenuItem disabled>Нет вариантов</MenuItem>
                    )}
                  </TextField>
                )}
              </Field>

              <Field name="checkIn" validate={required}>
                {({ input, meta }) => (
                  <TextField
                    type="date"
                    label="Check-in"
                    InputLabelProps={{ shrink: true }}
                    {...input}
                    error={meta.touched && !!meta.error}
                    helperText={meta.touched && meta.error}
                  />
                )}
              </Field>

              <Field name="checkOut" validate={required}>
                {({ input, meta }) => (
                  <TextField
                    type="date"
                    label="Check-out"
                    InputLabelProps={{ shrink: true }}
                    {...input}
                    error={meta.touched && !!meta.error}
                    helperText={meta.touched && meta.error}
                  />
                )}
              </Field>

              <Field name="guests" validate={required}>
                {({ input, meta }) => (
                  <TextField
                    type="number"
                    label="Guests"
                    {...input}
                    error={meta.touched && !!meta.error}
                    helperText={meta.touched && meta.error}
                  />
                )}
              </Field>

              <Stack direction="row" spacing={2}>
                <Button type="submit" variant="contained" disabled={submitting || pristine}>
                  Send
                </Button>
              </Stack>
            </Stack>
          </form>
        )}
      />
    </Paper>
  );
}
